function validateForm(form) {
Array.from(form.querySelectorAll('input, select, textarea')).forEach(input => input.setCustomValidity(''));
const zoneCode = String(form.elements.zone_code?.value || '').trim();
const zoneName = String(form.elements.zone_name?.value || '').trim();
if (!zoneCode) {
toast('Vui lÃ²ng nháº­p mÃ£ khu', 'warning');
return setFieldError(form.elements.zone_code, 'Vui lÃ²ng nháº­p mÃ£ khu');
}
if (!zoneName) {
toast('Vui lÃ²ng nháº­p tÃªn khu', 'warning');
return setFieldError(form.elements.zone_name, 'Vui lÃ²ng nháº­p tÃªn khu');
}
const totalArea = numberField(form, 'total_area');
const longTermArea = numberField(form, 'long_term_allocated_area');
const publicUtilityArea = numberField(form, 'public_utility_area');
const leasedArea = numberField(form, 'leased_area');
const convertedArea = numberField(form, 'converted_area');
if (totalArea <= 0) {
toast('Tá»•ng diá»‡n tÃ­ch pháº£i lá»›n hÆ¡n 0', 'warning');
return setFieldError(form.elements.total_area, 'Tá»•ng diá»‡n tÃ­ch pháº£i lá»›n hÆ¡n 0');
}
for (const name of FUND_FIELDS) {
if (numberField(form, name) < 0) {
toast('Diá»‡n tÃ­ch khÃ´ng Ä‘Æ°á»£c Ã¢m', 'warning');
return setFieldError(form.elements[name], 'Diá»‡n tÃ­ch khÃ´ng Ä‘Æ°á»£c Ã¢m');
}
}
const expectedTotal = longTermArea + publicUtilityArea + leasedArea;
if (Math.abs(totalArea - expectedTotal) > 0.0001) {
toast('Tá»•ng diá»‡n tÃ­ch pháº£i báº±ng Äáº¥t giao dÃ i háº¡n + Äáº¥t cÃ´ng Ã­ch + Äáº¥t thuÃª', 'warning');
return setFieldError(form.elements.total_area, 'Tá»•ng diá»‡n tÃ­ch pháº£i báº±ng Äáº¥t giao dÃ i háº¡n + Äáº¥t cÃ´ng Ã­ch + Äáº¥t thuÃª');
}
if (convertedArea > longTermArea + 0.0001) {
toast('Äáº¥t chuyá»ƒn Ä‘á»•i khÃ´ng Ä‘Æ°á»£c lá»›n hÆ¡n diá»‡n tÃ­ch Ä‘áº¥t giao dÃ i háº¡n', 'warning');
return setFieldError(form.elements.converted_area, 'Äáº¥t chuyá»ƒn Ä‘á»•i khÃ´ng Ä‘Æ°á»£c lá»›n hÆ¡n diá»‡n tÃ­ch Ä‘áº¥t giao dÃ i háº¡n');
}
let usageTotal = 0;
for (const input of Array.from(form.querySelectorAll('.agricultural-land-usage-area'))) {
const value = Number(String(input.value || '0').replace(',', '.')) || 0;
if (value < 0) {
toast('Diá»‡n tÃ­ch cÆ¡ cáº¥u sá»­ dá»¥ng Ä‘áº¥t khÃ´ng Ä‘Æ°á»£c Ã¢m', 'warning');
return setFieldError(input, 'Diá»‡n tÃ­ch khÃ´ng Ä‘Æ°á»£c Ã¢m');
}
usageTotal += value;
}
if (usageTotal > totalArea + 0.0001) {
toast('Tá»•ng diá»‡n tÃ­ch cÃ¡c loáº¡i sá»­ dá»¥ng Ä‘áº¥t khÃ´ng Ä‘Æ°á»£c lá»›n hÆ¡n tá»•ng diá»‡n tÃ­ch khu', 'warning');
return setFieldError(form.elements.total_area, 'Tá»•ng cÆ¡ cáº¥u sá»­ dá»¥ng Ä‘áº¥t Ä‘ang lá»›n hÆ¡n tá»•ng diá»‡n tÃ­ch khu');
}
return true;
}
